      var built=buildSentenceIndexFromScope(scope,artifact()),ids=Object.keys(built.sentenceIndex),processed=0;
      state.auditRun.id=built.runId;state.auditRun.startedAt=built.startedAt;state.auditRun.total=ids.length;
      for(var i=0;i<ids.length;i++){processed++;state.auditRun.processed=processed;state.auditRun.findings=Object.keys(built.audits).length;if(processed===1||processed%20===0)render();await new Promise(function(resolve){setTimeout(resolve,0);});}
