  function tabs(){return'<div class="literature-tabs" role="tablist">'+[['board','证据看板'],['audit','句子队列'],['local','局部反查'],['annotations','阅读批注'],['imported','已导入'],['matrix','证据矩阵'],['format','格式与导出']].map(function(item){return'<button role="tab" aria-selected="'+(state.view===item[0])+'" class="'+(state.view===item[0]?'active':'')+'" data-view="'+item[0]+'">'+item[1]+'</button>';}).join('')+'</div>';}
