  function annotationsView(){var annotations=artifact().annotations||{},items=Object.keys(annotations).map(function(id){return annotations[id];}).sort(function(a,b){return String(b.updatedAt||'').localeCompare(String(a.updatedAt||''));}),visible=state.annotationFilter==='all'?items:items.filter(function(item){return item.type===state.annotationFilter;});var controls=annotationFilterControls(items);if(state.annotationDraft)return annotationEditor()+'<div class="literature-section-title">已有批注 '+items.length+' 条</div>'+controls+annotationList(visible);return'<div class="literature-section-head"><div><strong>阅读批注 '+items.length+' 条</strong><p>所有批注都锚定原文；正文变化后会明确显示定位状态。</p></div></div>'+controls+annotationList(visible);}
  function annotationList(items){if(!items.length)return'<div class="literature-empty"><strong>'+(state.annotationFilter==='all'?'还没有阅读批注':'此类型暂无批注')+'</strong><p>'+(state.annotationFilter==='all'?'在左侧正文中选择句子或段落，然后点击浮动工具栏里的“批注”。':'切换到其他类型，或在正文中新增批注。')+'</p></div>';return'<div class="literature-annotation-list">'+items.map(function(item){var meta=ANNOTATION_TYPES[item.type]||ANNOTATION_TYPES.note,status=state.annotationStatuses[item.id]||annotationResolution(item).status,title=item.title||item.anchor&&item.anchor.quote||meta.label;return'<article class="literature-annotation-item type-'+item.type+'"><div class="literature-annotation-head"><span class="literature-annotation-type"><b aria-hidden="true">'+meta.icon+'</b> '+meta.label+'</span><span class="literature-annotation-status status-'+status+'">'+(ANNOTATION_STATUS[status]||ANNOTATION_STATUS.unlocated)+'</span></div><h4>'+esc(title)+'</h4><p class="literature-annotation-quote">'+esc(item.anchor&&item.anchor.quote||'')+'</p>'+(item.note?'<p class="literature-annotation-note">'+esc(item.note)+'</p>':'')+'<div class="literature-annotation-actions"><button type="button" data-annotation-jump="'+esc(item.id)+'" '+(status==='resolved'?'':'disabled')+'>跳转原文</button><button type="button" data-annotation-edit="'+esc(item.id)+'">编辑</button><button type="button" data-annotation-delete="'+esc(item.id)+'">删除</button></div></article>';}).join('')+'</div>';}
  function emptyLocal(){var draftCount=Object.keys((artifact().searchSessions)||{}).filter(function(id){return artifact().searchSessions[id]&&artifact().searchSessions[id].status!=='completed';}).length;return'<div class="literature-empty"><strong>从研究问题或一句原文开始找依据</strong><p>大型检索任务会引导你明确意图、配置策略、比较候选并分配到章节；系统不会自动修改正文。</p>'+(draftCount?'<button type="button" data-action="resume-search">继续未完成检索</button>':'')+'<button type="button" data-action="new-search">开始智能检索</button><button type="button" data-action="audit">先做全文引用审计</button></div>';}
