  function evidenceCard(p){var lit=artifact(),inCart=lit.cart.paperIds.indexOf(p.paperId)>=0,sel=lit.cart.selections[p.paperId]||{},summary=p.abstract||'当前来源未提供摘要，仅基于题名和元数据判断。',method=p.methods||'未从来源元数据中识别研究方法。',canInsert=!!(state.claim&&state.claim.anchor);return'<article class="evidence-card"><div class="evidence-card-head"><div><h4>'+esc(p.title)+'</h4><p>'+esc(p.authors||'作者未知')+' · '+esc(p.journal||'来源未知')+' · '+esc(p.year||'年份未知')+'</p></div><span class="evidence-score">'+Number((p.scores||{}).total||0)+'</span></div><div class="evidence-tags"><span>'+esc(p.source||'多源')+'</span>'+(p.doi?'<span>DOI 已提供</span>':'<span>DOI 缺失</span>')+(p.citations?'<span>被引 '+esc(p.citations)+'</span>':'')+'</div><details open><summary>为什么适合当前论点</summary><p>主题相关 '+Number((p.scores||{}).relevance||0)+'%，质量信号 '+Number((p.scores||{}).quality||0)+'%。命中题名/摘要中的论点关键词，最终关系需人工确认。</p></details><details><summary>摘要与方法</summary><p>'+esc(summary)+'</p><p><strong>方法：</strong>'+esc(method)+'</p></details><div class="evidence-actions"><button type="button" data-cart="'+esc(p.paperId)+'">'+(inCart?'移出候选篮':'加入候选篮')+'</button>'+(inCart?'<select data-relation="'+esc(p.paperId)+'">'+Object.keys(RELATIONS).map(function(k){return'<option value="'+k+'" '+(sel.relation===k?'selected':'')+'>'+RELATIONS[k]+'</option>';}).join('')+'</select>'+(canInsert?'<button class="literature-primary" type="button" data-confirm="'+esc(p.paperId)+'">确认引用</button>':'<span class="literature-insert-hint">选择正文位置后可插入引用</span>'):'')+'</div></article>';}
  function localView(){if(!state.claim)return emptyLocal();var html=claimEditor();if(state.loading)html+='<div class="literature-loading" aria-live="polite">正在按论点和文献角色检索…</div>';if(state.error)html+='<div class="literature-error" aria-live="polite">'+esc(state.error)+'</div>';if(state.results.length)html+='<div class="evidence-list"><div class="literature-section-title">候选证据 '+state.results.length+' 篇</div>'+state.results.map(evidenceCard).join('')+'</div>';else if(state.searchStatus==='completed')html+='<div class="literature-empty literature-search-empty" aria-live="polite"><strong>检索完成，未找到合适候选</strong><p>请尝试缩短论点、放宽关键词、补充学科信息，或减少文献关系类型后重新检索。</p><button type="button" data-action="search">调整后重新检索</button></div>';return html;}
