  function clearSentenceEvidenceHighlights(){document.querySelectorAll('[data-sentence-evidence-highlight]').forEach(function(el){el.classList.remove('sentence-evidence-pending','sentence-evidence-candidate','sentence-evidence-confirmed','sentence-evidence-ai-risk');delete el.dataset.sentenceEvidenceHighlight;});}
  function renderSentenceEvidenceHighlights(){clearSentenceEvidenceHighlights();var lit=artifact(),items=lit.sentenceIndex||{};Object.keys(items).forEach(function(id){var item=items[id],resolved=window.resolveTextAnchor&&item.anchor?resolveTextAnchor(item.anchor):null;if(!resolved||resolved.status!=='resolved'||!resolved.el)return;resolved.el.dataset.sentenceEvidenceHighlight=id;if((lit.audits||{})[id]&&lit.audits[id].status==='pending')resolved.el.classList.add('sentence-evidence-pending');if(((lit.sentenceCandidates||{})[id]||[]).length)resolved.el.classList.add('sentence-evidence-candidate');if(Number(item.aiRisk||0)>=50)resolved.el.classList.add('sentence-evidence-ai-risk');});}
